#!/usr/bin/env python3
"""Offline compiler: complete microservice invocation path policies -> stable
minimal enforcement automaton.

Reads JSONL requests on stdin, writes one JSON object per input line on stdout.
Standard library only.  See the task contract for the exact semantics.
"""

import json
import re
import sys
from collections import deque
from operator import getitem

# --------------------------------------------------------------------------
# published limits
# --------------------------------------------------------------------------
LINE_BYTES = 1048576
SCAN_DEPTH = 64

MAX_SERVICES = 24
MAX_SERVICE_SCALARS = 64
MAX_RULES = 32
MAX_NODES = 256
MAX_ARGS = 32
MAX_ATOM_PATH = 16
MAX_ATOMS = 10
MAX_QUERIES = 256
MAX_QUERY_TOKENS = 4096
MAX_QUERY_TOTAL = 16384

TUPLE_CAP = 20000

# rounds of Moore refinement before falling back to Hopcroft
MOORE_ROUNDS = 48

# --------------------------------------------------------------------------
# error payloads
# --------------------------------------------------------------------------
ERR_JSON = b'{"ok":false,"error":"E_JSON"}\n'
ERR_SCHEMA = b'{"ok":false,"error":"E_SCHEMA"}\n'
ERR_LIMIT = b'{"ok":false,"error":"E_LIMIT"}\n'
ERR_COMPLEXITY = b'{"ok":false,"error":"E_COMPLEXITY"}\n'


class SchemaErr(Exception):
    pass


class LimitErr(Exception):
    pass


class ComplexErr(Exception):
    pass


# --------------------------------------------------------------------------
# stage 1/2/3 helpers
# --------------------------------------------------------------------------
_SURROGATE = re.compile('[\ud800-\udfff]')


def depth_exceeded(text):
    """Preliminary bracket scan; True when the nesting depth exceeds 64."""
    depth = 0
    in_str = False
    esc = False
    for ch in text:
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch == '{' or ch == '[':
            depth += 1
            if depth > SCAN_DEPTH:
                return True
        elif ch == '}' or ch == ']':
            if depth:
                depth -= 1
    return False


def _reject_constant(_value):
    raise ValueError('forbidden numeric constant')


def _object_pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            raise ValueError('duplicate object key')
        out[key] = value
    return out


def parse_json(text):
    return json.loads(text, parse_constant=_reject_constant,
                      object_pairs_hook=_object_pairs)


# --------------------------------------------------------------------------
# stage 4: unicode scalar validity + schema
# --------------------------------------------------------------------------
def check_scalars(obj):
    """Every string (keys and values) must hold valid Unicode scalar values."""
    stack = [obj]
    push = stack.append
    pop = stack.pop
    search = _SURROGATE.search
    while stack:
        value = pop()
        kind = type(value)
        if kind is str:
            if search(value) is not None:
                raise SchemaErr()
        elif kind is dict:
            for key, sub in value.items():
                if search(key) is not None:
                    raise SchemaErr()
                push(sub)
        elif kind is list:
            for sub in value:
                push(sub)


CONST_OPS = frozenset(('true', 'false'))
ATOM_OPS = frozenset(('match', 'startswith', 'endswith', 'contains'))
NODE_KEYS = {
    'true': frozenset(('op',)),
    'false': frozenset(('op',)),
    'match': frozenset(('op', 'path')),
    'startswith': frozenset(('op', 'path')),
    'endswith': frozenset(('op', 'path')),
    'contains': frozenset(('op', 'path')),
    'not': frozenset(('op', 'arg')),
    'and': frozenset(('op', 'args')),
    'or': frozenset(('op', 'args')),
}


class Ctx(object):
    __slots__ = ('index', 'nodes', 'atoms', 'atom_list', 'args_max',
                 'path_max')

    def __init__(self, index):
        self.index = index
        self.nodes = 0
        self.atoms = {}
        self.atom_list = []
        self.args_max = 0
        self.path_max = 0


def read_path(value, ctx):
    if type(value) is not list:
        raise SchemaErr()
    index = ctx.index
    out = []
    for token in value:
        if type(token) is not str:
            raise SchemaErr()
        if token not in index:
            raise SchemaErr()
        out.append(token)
    length = len(out)
    if length > ctx.path_max:
        ctx.path_max = length
    return tuple(out)


def parse_expr(value, ctx):
    if type(value) is not dict:
        raise SchemaErr()
    op = value.get('op')
    if type(op) is not str:
        raise SchemaErr()
    allowed = NODE_KEYS.get(op)
    if allowed is None:
        raise SchemaErr()
    if set(value.keys()) != allowed:
        raise SchemaErr()
    ctx.nodes += 1
    if op in CONST_OPS:
        return ('c', 1 if op == 'true' else 0)
    if op in ATOM_OPS:
        path = read_path(value['path'], ctx)
        key = (op, path)
        ident = ctx.atoms.get(key)
        if ident is None:
            ident = len(ctx.atom_list)
            ctx.atoms[key] = ident
            ctx.atom_list.append(key)
        return ('a', ident)
    if op == 'not':
        return ('n', parse_expr(value['arg'], ctx))
    args = value['args']
    if type(args) is not list:
        raise SchemaErr()
    if len(args) > ctx.args_max:
        ctx.args_max = len(args)
    return ('&' if op == 'and' else '|', [parse_expr(a, ctx) for a in args])


def validate(obj):
    """Stages 4 and 5.  Returns a dict describing the validated request."""
    check_scalars(obj)
    if type(obj) is not dict:
        raise SchemaErr()
    if len(obj) != 3:
        raise SchemaErr()
    try:
        services = obj['services']
        rules = obj['rules']
        queries = obj['queries']
    except KeyError:
        raise SchemaErr()

    if type(services) is not list:
        raise SchemaErr()
    seen = set()
    for token in services:
        if type(token) is not str:
            raise SchemaErr()
        if not token:
            raise SchemaErr()
        if token in seen:
            raise SchemaErr()
        seen.add(token)
    index = {}
    for pos, token in enumerate(services):
        index[token] = pos
    sigma = len(services)

    if type(rules) is not list:
        raise SchemaErr()
    ctx = Ctx(index)
    compiled = []
    for rule in rules:
        if type(rule) is not dict:
            raise SchemaErr()
        if len(rule) != 2:
            raise SchemaErr()
        try:
            action = rule['action']
            when = rule['when']
        except KeyError:
            raise SchemaErr()
        if action == 'allow':
            flag = 1
        elif action == 'drop':
            flag = 0
        else:
            raise SchemaErr()
        compiled.append((flag, parse_expr(when, ctx)))

    if type(queries) is not list:
        raise SchemaErr()
    paths = []
    total_tokens = 0
    for query in queries:
        if type(query) is not list:
            raise SchemaErr()
        row = []
        for token in query:
            if type(token) is not str:
                raise SchemaErr()
            pos = index.get(token)
            if pos is None:
                raise SchemaErr()
            row.append(pos)
        total_tokens += len(row)
        paths.append(row)

    # ---- stage 5: declared size limits --------------------------------
    svc_len_max = 0
    for token in services:
        length = len(token)
        if length > svc_len_max:
            svc_len_max = length
    query_len_max = 0
    for row in paths:
        if len(row) > query_len_max:
            query_len_max = len(row)

    if sigma > MAX_SERVICES or svc_len_max > MAX_SERVICE_SCALARS:
        raise LimitErr()
    if len(rules) > MAX_RULES:
        raise LimitErr()
    if ctx.nodes > MAX_NODES:
        raise LimitErr()
    if ctx.args_max > MAX_ARGS:
        raise LimitErr()
    if ctx.path_max > MAX_ATOM_PATH:
        raise LimitErr()
    if len(ctx.atom_list) > MAX_ATOMS:
        raise LimitErr()
    if len(queries) > MAX_QUERIES:
        raise LimitErr()
    if query_len_max > MAX_QUERY_TOKENS:
        raise LimitErr()
    if total_tokens > MAX_QUERY_TOTAL:
        raise LimitErr()

    return {
        'sigma': sigma,
        'index': index,
        'rules': compiled,
        'atoms': ctx.atom_list,
        'queries': paths,
    }


# --------------------------------------------------------------------------
# atomic monitors
# --------------------------------------------------------------------------
def build_monitors(atoms, sigma, index):
    """Return per-atom (transition table over symbols, true state)."""
    tables = []
    true_states = []
    for op, path in atoms:
        m = len(path)
        psym = [index[token] for token in path]
        if op == 'match' or op == 'startswith':
            states = m + 2
            fail = m + 1
            table = [[0] * states for _ in range(sigma)]
            for a in range(sigma):
                row = table[a]
                for k in range(m):
                    row[k] = (k + 1) if psym[k] == a else fail
                row[m] = fail if op == 'match' else m
                row[fail] = fail
            true = m
        else:
            states = m + 1
            true = m
            table = [[0] * states for _ in range(sigma)]
            absorbing = (op == 'contains')
            for k in range(states):
                if absorbing and k == m:
                    for a in range(sigma):
                        table[a][m] = m
                    continue
                base = psym[:k]
                for a in range(sigma):
                    word = base + [a]
                    top = m if m < k + 1 else k + 1
                    j = top
                    while j > 0:
                        off = k + 1 - j
                        ok = True
                        for i in range(j):
                            if psym[i] != word[off + i]:
                                ok = False
                                break
                        if ok:
                            break
                        j -= 1
                    table[a][k] = j
        tables.append(table)
        true_states.append(true)
    return tables, true_states


def product_bfs(k, coltabs, sigma, cap):
    """Reachable synchronous product; raises ComplexErr above `cap` tuples."""
    init = (0,) * k
    index = {init: 0}
    states = [init]
    trans = []
    head = 0
    limit = len(index) >= cap
    while head < len(states):
        tup = states[head]
        head += 1
        row = [0] * sigma
        for a in range(sigma):
            nxt = tuple(map(getitem, coltabs[a], tup))
            ident = index.get(nxt)
            if ident is None:
                if limit:
                    raise ComplexErr()
                ident = len(states)
                index[nxt] = ident
                states.append(nxt)
                if len(index) >= cap:
                    limit = True
            row[a] = ident
        trans.append(row)
    return states, trans


# --------------------------------------------------------------------------
# boolean function over atom truth values (bitset of 2**k assignments)
# --------------------------------------------------------------------------
def expr_mask(tree, var_masks, everything):
    kind = tree[0]
    if kind == 'c':
        return everything if tree[1] else 0
    if kind == 'a':
        return var_masks[tree[1]]
    if kind == 'n':
        return everything ^ expr_mask(tree[1], var_masks, everything)
    if kind == '&':
        result = everything
        for sub in tree[1]:
            result &= expr_mask(sub, var_masks, everything)
            if not result:
                break
        return result
    result = 0
    for sub in tree[1]:
        result |= expr_mask(sub, var_masks, everything)
        if result == everything:
            break
    return result


# --------------------------------------------------------------------------
# minimisation
# --------------------------------------------------------------------------
def moore(n, sigma, trans, part, blocks):
    """Partition refinement by rounds; returns (part, nblocks, converged)."""
    for _ in range(MOORE_ROUNDS):
        getter = part.__getitem__
        marks = {}
        newpart = [0] * n
        count = 0
        for q in range(n):
            sig = (part[q],) + tuple(map(getter, trans[q]))
            ident = marks.get(sig)
            if ident is None:
                ident = count
                count += 1
                marks[sig] = ident
            newpart[q] = ident
        if count == blocks or count == n:
            return newpart, count, True
        part = newpart
        blocks = count
    return part, blocks, False


def hopcroft(n, sigma, trans, part, blocks):
    """Refine `part` to the coarsest stable partition."""
    members = [[] for _ in range(blocks)]
    for q in range(n):
        members[part[q]].append(q)
    block_of = part[:]

    preds = []
    for c in range(sigma):
        counts = [0] * n
        for q in range(n):
            counts[trans[q][c]] += 1
        start = [0] * (n + 1)
        total = 0
        for i in range(n):
            start[i] = total
            total += counts[i]
        start[n] = total
        flat = [0] * n
        cursor = start[:]
        for q in range(n):
            target = trans[q][c]
            flat[cursor[target]] = q
            cursor[target] += 1
        preds.append((start, flat))

    waiting = deque()
    queued = [False] * blocks
    for ident in range(blocks):
        waiting.append(ident)
        queued[ident] = True
    counter = [0] * blocks
    marked = bytearray(n)

    while waiting:
        current = waiting.popleft()
        queued[current] = False
        source = members[current]
        if source is None:
            continue
        for c in range(sigma):
            start, flat = preds[c]
            touched = []
            hits = []
            for state in source:
                for pos in range(start[state], start[state + 1]):
                    q = flat[pos]
                    ident = block_of[q]
                    if counter[ident] == 0:
                        touched.append(ident)
                    counter[ident] += 1
                    marked[q] = 1
                    hits.append(q)
            for ident in touched:
                inside = counter[ident]
                counter[ident] = 0
                group = members[ident]
                if inside == len(group):
                    continue
                kept = []
                moved = []
                for q in group:
                    if marked[q]:
                        kept.append(q)
                    else:
                        moved.append(q)
                for q in hits:
                    marked[q] = 0
                hits = []
                if len(moved) <= len(kept):
                    members[ident] = kept
                    fresh = moved
                else:
                    members[ident] = moved
                    fresh = kept
                new_id = len(members)
                members.append(fresh)
                for q in fresh:
                    block_of[q] = new_id
                counter.append(0)
                queued.append(False)
                if queued[ident]:
                    queued[new_id] = True
                    waiting.append(new_id)
                else:
                    small = new_id if len(fresh) <= len(members[ident]) else ident
                    queued[small] = True
                    waiting.append(small)
            for q in hits:
                marked[q] = 0
            hits = []
    return block_of, len([1 for g in members if g])


def minimize(n, sigma, trans, accept):
    """Returns canonical (accept, next, distance) of the minimal DFA."""
    if n == 1:
        part = [0]
        blocks = 1
    else:
        has0 = 0
        has1 = 0
        for value in accept:
            if value:
                has1 = 1
            else:
                has0 = 1
        if has0 and has1:
            part = accept[:]
            blocks = 2
        else:
            part = [0] * n
            blocks = 1
        if blocks < n:
            part, blocks, done = moore(n, sigma, trans, part, blocks)
            if not done:
                part, blocks = hopcroft(n, sigma, trans, part, blocks)

    # quotient automaton
    reps = [-1] * blocks
    for q in range(n):
        ident = part[q]
        if reps[ident] < 0:
            reps[ident] = q
    qtrans = []
    qaccept = []
    for ident in range(blocks):
        rep = reps[ident]
        qtrans.append([part[x] for x in trans[rep]])
        qaccept.append(1 if accept[rep] else 0)
    start = part[0]

    # canonical breadth-first numbering, alphabet order
    order = [start]
    numbering = {start: 0}
    head = 0
    while head < len(order):
        ident = order[head]
        head += 1
        for target in qtrans[ident]:
            if target not in numbering:
                numbering[target] = len(order)
                order.append(target)

    count = len(order)
    nxt = [[0] * sigma for _ in range(count)]
    acc = [False] * count
    for new_id, ident in enumerate(order):
        row = qtrans[ident]
        out = nxt[new_id]
        for c in range(sigma):
            out[c] = numbering[row[c]]
        acc[new_id] = bool(qaccept[ident])

    # distance: fewest further tokens to an accepting state
    reverse = [[] for _ in range(count)]
    for q in range(count):
        for target in nxt[q]:
            if target != q:
                reverse[target].append(q)
    dist = [None] * count
    queue = deque()
    for q in range(count):
        if acc[q]:
            dist[q] = 0
            queue.append(q)
    while queue:
        state = queue.popleft()
        step = dist[state] + 1
        for prev in reverse[state]:
            if dist[prev] is None:
                dist[prev] = step
                queue.append(prev)
    return acc, nxt, dist


# --------------------------------------------------------------------------
# compilation of one request
# --------------------------------------------------------------------------
def compile_request(info):
    sigma = info['sigma']
    atoms = info['atoms']
    k = len(atoms)
    rules = info['rules']
    queries = info['queries']

    tables, true_states = build_monitors(atoms, sigma, info['index'])

    size = 1 << k
    everything = (1 << size) - 1
    var_masks = []
    for i in range(k):
        mask = 0
        bit = 1 << i
        for b in range(size):
            if b & bit:
                mask |= 1 << b
        var_masks.append(mask)

    allow = 0
    drop = 0
    for flag, tree in rules:
        mask = expr_mask(tree, var_masks, everything)
        if flag:
            allow |= mask
        else:
            drop |= mask
    accepted = allow & (everything ^ drop)

    if accepted == 0 or accepted == everything:
        flag = bool(accepted)
        acc = [flag]
        nxt = [[0] * sigma]
        dist = [0 if flag else None]
    else:
        coltabs = [[tables[j][a] for j in range(k)] for a in range(sigma)]
        states, trans = product_bfs(k, coltabs, sigma, TUPLE_CAP)

        relevant = []
        table = [(accepted >> b) & 1 for b in range(size)]
        for i in range(k):
            bit = 1 << i
            for b in range(size):
                if table[b] != table[b ^ bit]:
                    relevant.append(i)
                    break
        if len(relevant) < k:
            coltabs = [[tables[j][a] for j in relevant] for a in range(sigma)]
            states, trans = product_bfs(len(relevant), coltabs, sigma,
                                        TUPLE_CAP)
            true_states = [true_states[j] for j in relevant]

        bits = []
        for i, true in enumerate(true_states):
            column = [0] * len(tables[0][0]) if False else None
        # truth-value bit contributed by each atom's monitor state
        bit_tabs = []
        for i, true in enumerate(true_states):
            width = len(tables[0][0])
        # rebuild widths from the monitors actually in use
        used = relevant if len(relevant) < k else list(range(k))
        bit_tabs = []
        for i, j in enumerate(used):
            width = len(tables[j][0]) if sigma else (true_states[j] + 2)
            column = [0] * width
            column[true_states[j]] = 1 << i
            bit_tabs.append(column)
        table = [(accepted >> b) & 1 for b in range(size)]
        accept = [table[sum(map(getitem, bit_tabs, tup))] for tup in states]
        acc, nxt, dist = minimize(len(states), sigma, trans, accept)

    out_queries = []
    for path in queries:
        state = 0
        for symbol in path:
            state = nxt[state][symbol]
        out_queries.append({'state': state, 'allow': acc[state],
                            'distance': dist[state]})

    return {
        'ok': True,
        'dfa': {'start': 0, 'accept': acc, 'next': nxt, 'distance': dist},
        'queries': out_queries,
    }


# --------------------------------------------------------------------------
# driver
# --------------------------------------------------------------------------
def handle_line(raw):
    if len(raw) > LINE_BYTES:
        return ERR_LIMIT
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return ERR_JSON
    if depth_exceeded(text):
        return ERR_LIMIT
    try:
        obj = parse_json(text)
    except ValueError:
        return ERR_JSON
    except RecursionError:
        return ERR_JSON
    try:
        info = validate(obj)
    except SchemaErr:
        return ERR_SCHEMA
    except LimitErr:
        return ERR_LIMIT
    try:
        result = compile_request(info)
    except ComplexErr:
        return ERR_COMPLEXITY
    except SchemaErr:
        return ERR_SCHEMA
    except LimitErr:
        return ERR_LIMIT
    except RecursionError:
        return ERR_LIMIT
    return json.dumps(result, separators=(',', ':')).encode('utf-8') + b'\n'


def main():
    data = sys.stdin.buffer.read()
    out = sys.stdout.buffer
    if data:
        lines = data.split(b'\n')
        if lines[-1] == b'':
            lines.pop()
        for raw in lines:
            try:
                payload = handle_line(raw)
            except Exception:                      # pragma: no cover
                payload = ERR_JSON
            out.write(payload)
    out.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
