#!/usr/bin/env python3
"""Independent brute-force checker for the policy compiler."""
import itertools
import json
import random
import subprocess
import sys

MAIN = '/workspace/submission/main.py'


# ---------------------------------------------------------------- semantics
def eval_expr(e, w):
    op = e['op']
    if op == 'true':
        return True
    if op == 'false':
        return False
    if op in ('match', 'startswith', 'endswith', 'contains'):
        p = e['path']
        m = len(p)
        if op == 'match':
            return w == p
        if op == 'startswith':
            return len(w) >= m and w[:m] == p
        if op == 'endswith':
            return len(w) >= m and w[len(w) - m:] == p
        # contains
        if m == 0:
            return True
        for i in range(len(w) - m + 1):
            if w[i:i + m] == p:
                return True
        return False
    if op == 'not':
        return not eval_expr(e['arg'], w)
    if op == 'and':
        return all(eval_expr(a, w) for a in e['args'])
    if op == 'or':
        return any(eval_expr(a, w) for a in e['args'])
    raise AssertionError('bad op ' + op)


def member(rules, w):
    allowed = False
    dropped = False
    for r in rules:
        v = eval_expr(r['when'], w)
        if r['action'] == 'allow':
            allowed = allowed or v
        else:
            dropped = dropped or v
    return allowed and not dropped


# ---------------------------------------------------------------- checking
def check(req, out, B, B2, verbose=False):
    services = req['services']
    sigma = len(services)
    rules = req['rules']
    assert out.get('ok') is True, out
    assert set(out.keys()) == {'ok', 'dfa', 'queries'}, out.keys()
    dfa = out['dfa']
    assert set(dfa.keys()) == {'start', 'accept', 'next', 'distance'}
    assert dfa['start'] == 0 and type(dfa['start']) is int
    n = len(dfa['accept'])
    assert n >= 1
    assert len(dfa['next']) == n and len(dfa['distance']) == n
    for a in dfa['accept']:
        assert type(a) is bool
    for row in dfa['next']:
        assert len(row) == sigma
        for t in row:
            assert type(t) is int and 0 <= t < n, row
    for d in dfa['distance']:
        assert d is None or (type(d) is int and d >= 0)

    nxt = dfa['next']
    acc = dfa['accept']

    def run(w):
        s = 0
        for x in w:
            s = nxt[s][x]
        return s

    # language equivalence on every word up to length B
    if sigma:
        words = []
        for length in range(B + 1):
            for tup in itertools.product(range(sigma), repeat=length):
                words.append(tup)
    else:
        words = [()]
    for tup in words:
        toks = [services[i] for i in tup]
        s = run(list(tup))
        want = member(rules, toks)
        assert acc[s] == want, ('language mismatch', toks, acc[s], want)

    # reachability
    seen = {0}
    stack = [0]
    while stack:
        q = stack.pop()
        for t in nxt[q]:
            if t not in seen:
                seen.add(t)
                stack.append(t)
    assert len(seen) == n, ('unreachable states', n, len(seen))

    # canonical numbering: BFS from 0 in alphabet order
    order = [0]
    known = {0}
    head = 0
    while head < len(order):
        q = order[head]
        head += 1
        for t in nxt[q]:
            if t not in known:
                known.add(t)
                order.append(t)
    assert order == list(range(n)), ('bad numbering', order)

    # minimality: distinct continuation behaviour up to length B2
    conts = []
    for length in range(B2 + 1):
        for tup in itertools.product(range(sigma), repeat=length):
            conts.append(tup)
    sig = []
    for q in range(n):
        vec = []
        for tup in conts:
            s = q
            for x in tup:
                s = nxt[s][x]
            vec.append(acc[s])
        sig.append(tuple(vec))
    assert len(set(sig)) == n, 'not minimal'

    # distances
    rev = [[] for _ in range(n)]
    for q in range(n):
        for t in nxt[q]:
            rev[t].append(q)
    dist = [None] * n
    from collections import deque
    dq = deque()
    for q in range(n):
        if acc[q]:
            dist[q] = 0
            dq.append(q)
    while dq:
        u = dq.popleft()
        for p in rev[u]:
            if dist[p] is None:
                dist[p] = dist[u] + 1
                dq.append(p)
    assert dist == dfa['distance'], ('distance', dist, dfa['distance'])

    # queries
    qs = out['queries']
    assert len(qs) == len(req['queries'])
    for path, got in zip(req['queries'], qs):
        assert set(got.keys()) == {'state', 'allow', 'distance'}
        idx = [services.index(t) for t in path]
        s = run(idx)
        assert got['state'] == s and type(got['state']) is int
        assert got['allow'] is acc[s]
        assert got['distance'] == dist[s]
    return n


# ---------------------------------------------------------------- generation
def rnd_expr(services, depth, rnd, atom_pool):
    choices = ['true', 'false', 'atom', 'atom', 'not', 'and', 'or']
    if depth <= 0:
        choices = ['true', 'false', 'atom', 'atom', 'atom']
    kind = rnd.choice(choices)
    if kind == 'atom':
        op, path = rnd.choice(atom_pool)
        return {'op': op, 'path': list(path)}
    if kind in ('true', 'false'):
        return {'op': kind}
    if kind == 'not':
        return {'op': 'not', 'arg': rnd_expr(services, depth - 1, rnd, atom_pool)}
    n = rnd.randint(0, 3)
    return {'op': kind,
            'args': [rnd_expr(services, depth - 1, rnd, atom_pool)
                     for _ in range(n)]}


def random_request(rnd):
    sigma = rnd.choice([0, 1, 2, 2, 3, 3, 4])
    tokens = ['t%d' % i for i in range(sigma)]
    if sigma and rnd.random() < 0.3:
        tokens = [rnd.choice(['a', 'aa', 'b', 'x y', '"q"', '\u00e9\u03b2'])
                  for _ in range(sigma)]
        tokens = list(dict.fromkeys(tokens))
        sigma = len(tokens)
    pool = []
    for op in ('match', 'startswith', 'endswith', 'contains'):
        for _ in range(3):
            m = rnd.choice([0, 1, 1, 2, 2, 3])
            m = min(m, sigma) if sigma else 0
            path = [rnd.choice(tokens) for _ in range(m)] if m else []
            if rnd.random() < 0.3 and path:
                path = [path[0]] * len(path)
            pool.append((op, tuple(path)))
    nrules = rnd.randint(0, 3)
    rules = []
    for _ in range(nrules):
        rules.append({'action': rnd.choice(['allow', 'allow', 'drop']),
                      'when': rnd_expr(tokens, rnd.randint(0, 3), rnd, pool)})
    queries = []
    for _ in range(rnd.randint(0, 6)):
        m = rnd.randint(0, 5)
        queries.append([rnd.choice(tokens) for _ in range(m)] if tokens else [])
    return {'services': tokens, 'rules': rules, 'queries': queries}


def run_program(payload):
    proc = subprocess.run([sys.executable, '-I', MAIN], input=payload,
                          capture_output=True, timeout=120)
    assert proc.returncode == 0, proc.stderr[:3000]
    return proc.stdout


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rnd = random.Random(seed)
    reqs = [random_request(rnd) for _ in range(count)]
    payload = b''.join(json.dumps(r, ensure_ascii=False).encode('utf-8') + b'\n'
                       for r in reqs)
    out = run_program(payload)
    lines = out.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    assert len(lines) == len(reqs), (len(lines), len(reqs))
    total = 0
    for req, line in zip(reqs, lines):
        obj = json.loads(line)
        total += check(req, obj, B=7, B2=7)
    print('checked %d random requests, %d total states' % (count, total))


if __name__ == '__main__':
    main()
