# --------------------------------------------------------------------------
def handle_line(raw):
    if len(raw) > LINE_BYTES:
        return ERR_LIMIT
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return ERR_JSON
    if depth_exceeded(text):
        return ERR_LIMIT
    try:
        obj = parse_json(text)
    except ValueError:
        return ERR_JSON
    except RecursionError:
        return ERR_JSON
    try:
        info = validate(obj)
    except SchemaErr:
        return ERR_SCHEMA
    except LimitErr:
        return ERR_LIMIT
    try:
        result = compile_request(info)
    except ComplexErr:
        return ERR_COMPLEXITY
    except (SchemaErr, LimitErr):
        return ERR_SCHEMA
    except RecursionError:
        return ERR_LIMIT
    return json.dumps(result, separators=(',', ':')).encode('utf-8') + b'\n'


