    data = sys.stdin.buffer.read()
    out = sys.stdout.buffer
    if data:
        lines = data.split(b'\n')
        if lines[-1] == b'':
            lines.pop()
        for raw in lines:
            try:
                payload = handle_line(raw)
            except Exception:                      # pragma: no cover
                payload = ERR_JSON
            out.write(payload)
    out.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())

