#!/usr/bin/env python3
"""Fully independent reference pipeline (semantic monitors, no transition tables).

Builds the product automaton by re-evaluating each atom's state from the whole
word (per the prose definition), labels states with the semantic membership
predicate, minimises with an independent implementation, canonicalises and
computes distances.  Output must equal the submission's byte for byte.
"""
import itertools, json, random, subprocess, sys
from collections import deque
sys.path.insert(0, '/workspace/dev')
from brute import member
from monitors_test import sem_state

MAIN = '/workspace/submission/main.py'


def collect_atoms(rules):
    atoms = []
    seen = set()

    def walk(e):
        op = e['op']
        if op in ('match', 'startswith', 'endswith', 'contains'):
            key = (op, tuple(e['path']))
            if key not in seen:
                seen.add(key)
                atoms.append(key)
        elif op == 'not':
            walk(e['arg'])
        elif op in ('and', 'or'):
            for a in e['args']:
                walk(a)
    for r in rules:
        walk(r['when'])
    return atoms


def reference(rq):
    services = rq['services']
    rules = rq['rules']
    sigma = len(services)
    atoms = collect_atoms(rules)

    def tup(word):
        return tuple(sem_state(op, list(p), word) for op, p in atoms)

    # product by BFS, successors computed semantically from the whole word
    init = tup([])
    index = {init: 0}
    words = [[]]
    order = [init]
    head = 0
    trans = []
    while head < len(order):
        t = order[head]
        w = words[head]
        head += 1
        row = []
        for c in range(sigma):
            nt = tup(w + [services[c]])
            ident = index.get(nt)
            if ident is None:
                ident = len(order)
                index[nt] = ident
                order.append(nt)
                words.append(w + [services[c]])
            row.append(ident)
        trans.append(row)
    n = len(order)
    accept = [member(rules, [services[i] for i in words[q]]) for q in range(n)]

    # independent minimisation: Moore to convergence
    part = [1 if a else 0 for a in accept]
    blocks = len(set(part))
    while blocks < n:
        marks = {}
        newp = [0] * n
        c = 0
        for q in range(n):
            sig = tuple([part[q]] + [part[t] for t in trans[q]])
            ident = marks.get(sig)
            if ident is None:
                ident = c
                c += 1
                marks[sig] = ident
            newp[q] = ident
        if c == blocks:
            break
        part, blocks = newp, c

    reps = {}
    for q in range(n):
        reps.setdefault(part[q], q)
    qtrans = [[part[t] for t in trans[reps[b]]] for b in range(blocks)]
    qacc = [accept[reps[b]] for b in range(blocks)]
    start = part[0]

    order2 = [start]
    num = {start: 0}
    head = 0
    while head < len(order2):
        b = order2[head]
        head += 1
        for t in qtrans[b]:
            if t not in num:
                num[t] = len(order2)
                order2.append(t)
    cnt = len(order2)
    nxt = [[num[t] for t in qtrans[b]] for b in order2]
    acc = [qacc[b] for b in order2]
    rev = [[] for _ in range(cnt)]
    for q in range(cnt):
        for t in nxt[q]:
            if t != q:
                rev[t].append(q)
    dist = [None] * cnt
    dq = deque()
    for q in range(cnt):
        if acc[q]:
            dist[q] = 0
            dq.append(q)
    while dq:
        u = dq.popleft()
        for p in rev[u]:
            if dist[p] is None:
                dist[p] = dist[u] + 1
                dq.append(p)

    qs = []
    for path in rq['queries']:
        s = 0
        for tok in path:
            s = nxt[s][services.index(tok)]
        qs.append({'state': s, 'allow': acc[s], 'distance': dist[s]})
    return {'ok': True,
            'dfa': {'start': 0, 'accept': acc, 'next': nxt, 'distance': dist},
            'queries': qs}


def random_small(rnd):
    sigma = rnd.choice([0, 1, 2, 3])
    toks = ['p%d' % i for i in range(sigma)]
    if sigma == 0:
        pool = [{'op': op, 'path': []} for op in
                ('match', 'startswith', 'endswith', 'contains')]
    else:
        pool = []
        for op in ('match', 'startswith', 'endswith', 'contains'):
            for _ in range(2):
                L = rnd.randint(0, 4)
                p = [rnd.choice(toks) for _ in range(L)]
                if p and rnd.random() < 0.4:
                    p = [p[0]] * len(p)
                pool.append({'op': op, 'path': p})

    def expr(d):
        if d <= 0 or rnd.random() < 0.4:
            if rnd.random() < 0.15:
                return {'op': rnd.choice(['true', 'false'])}
            return dict(rnd.choice(pool))
        k = rnd.choice(['not', 'and', 'or'])
        if k == 'not':
            return {'op': 'not', 'arg': expr(d - 1)}
        return {'op': k, 'args': [expr(d - 1) for _ in range(rnd.randint(0, 3))]}

    rules = [{'action': rnd.choice(['allow', 'allow', 'drop']),
              'when': expr(rnd.randint(0, 2))} for _ in range(rnd.randint(0, 3))]
    queries = [[rnd.choice(toks) for _ in range(rnd.randint(0, 6))]
               for _ in range(rnd.randint(0, 4))] if toks else [[] for _ in range(rnd.randint(0, 3))]
    return {'services': toks, 'rules': rules, 'queries': queries}


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 60
    rnd = random.Random(seed)
    reqs = [random_small(rnd) for _ in range(count)]
    payload = b''.join(json.dumps(r).encode() + b'\n' for r in reqs)
    p = subprocess.run([sys.executable, '-I', MAIN], input=payload, capture_output=True)
    assert p.returncode == 0, p.stderr[:2000]
    lines = [l for l in p.stdout.split(b'\n') if l]
    assert len(lines) == len(reqs)
    same = 0
    for i, (rq, line) in enumerate(zip(reqs, lines)):
        got = json.loads(line)
        want = reference(rq)
        if got != want:
            print('DIFF case', i)
            print(' req ', json.dumps(rq)[:600])
            print(' got ', json.dumps(got)[:600])
            print(' want', json.dumps(want)[:600])
            sys.exit(1)
        same += 1
    print('reference pipeline: %d/%d identical' % (same, len(reqs)))


if __name__ == '__main__':
    main()
